function lnrP_heirBuyerResidence(next){q('Вы проживали на территории ЛНР на момент принятия ЛНР в состав Российской Федерации?',[['Да, проживал и сейчас проживаю в ЛНР',()=>lnrP_heirBuyerProof(next)],['Да, ранее проживал в ЛНР, но сейчас проживаю или зарегистрирован в другом регионе РФ',()=>lnrP_heirBuyerProof(next)],['Нет',()=>pending('Для этого маршрута требуется отдельная правовая оценка')]],accession)}
function lnrP_heirBuyerCitizen(next){q('Являетесь ли вы как приобретатель гражданином Российской Федерации?',[['Да',()=>lnrP_heirBuyerResidence(next)],['Нет',()=>pending('Требуется определить применимый порядок регистрации')]])}
function lnrP_heirSaleFinal(){result('green','🟢 ПОСТОЯННАЯ РЕГИСТРАЦИЯ РФ НА ПОКУПАТЕЛЯ','<p><b>Цепочка:</b> свидетельство о регистрации транспортного средства ЛНР на умершего → свидетельство о праве на наследство → ДКП наследник–покупатель → регистрация РФ на покупателя.</p><p>Предварительно регистрировать транспортное средство на наследника не требуется. По принятой для Навигатора практике наследник лично участвует в оформлении в МРЭО.</p><p>При успешной регистрации выдаются <b>СТС РФ, ПТС на бумажном носителе и государственные регистрационные номерные знаки РФ</b>.</p><h3>💰 Безопасная передача денег</h3><p>Не рекомендуется проводить полный расчёт только после приёма заявления МРЭО: принятие документов не гарантирует регистрацию. Заранее согласуйте с наследником порядок оплаты в ДКП: проверка документов и автомобиля → совместное обращение в МРЭО с личным участием наследника → подтверждение успешного регистрационного оформления → окончательный расчёт в согласованный срок. Аванс фиксируйте письменно; наличные — распиской, банковский перевод — с понятным назначением платежа. Если оплата производится до регистрации, предусмотрите в договоре порядок возврата денег при отказе.</p><h3>🛑 Если отказали</h3><p>Получите письменное решение с конкретным правовым основанием.</p>')}
function lnrP_heirGiftFinal(){result('green','🟢 ПОСТОЯННАЯ РЕГИСТРАЦИЯ РФ НА ОДАРЯЕМОГО','<p><b>Цепочка:</b> свидетельство о регистрации транспортного средства ЛНР на умершего → свидетельство о праве на наследство → договор дарения наследник–одаряемый → регистрация РФ на одаряемого.</p><p>Предварительно регистрировать транспортное средство на наследника не требуется. По принятой для Навигатора практике наследник лично участвует в МРЭО.</p><p>При успешной регистрации выдаются <b>СТС РФ, ПТС на бумажном носителе и государственные регистрационные номерные знаки РФ</b>.</p><h3>🛑 Если отказали</h3><p>Получите письменное решение с конкретным правовым основанием.</p>')}
function lnrP_heirParticipation(next){q('Готов ли наследник, указанный в свидетельстве о праве на наследство, лично участвовать в оформлении транспортного средства в МРЭО?',[['Да, готов',()=>lnrP_heirBuyerCitizen(next)],['Нет, не может или не хочет участвовать',()=>lnrP_five('Наследник не участвует в оформлении. Практический маршрут фактического владельца — регистрация на 5 лет.')],['Наследник умер',()=>other('Новая наследственная цепочка')],['Связь с наследником утрачена',()=>lnrP_five('Связь с наследником утрачена. Практический маршрут фактического владельца — регистрация на 5 лет.')]])}
function lnrP_heirDisposition(){q('Как планируется оформить транспортное средство дальше?',[['Зарегистрировать транспортное средство на наследника',lnrP_inheritanceOwner],['Продать транспортное средство нынешнему владельцу',()=>lnrP_heirParticipation(lnrP_heirSaleFinal)],['Подарить транспортное средство нынешнему владельцу',()=>lnrP_heirParticipation(lnrP_heirGiftFinal)],['Другая ситуация / нет подходящего варианта',()=>other('Л-2В.2.2')]])}
function lnrP_inheritancePending(){result('yellow','🟡 НАСЛЕДСТВО ЕЩЁ НЕ ОФОРМЛЕНО','<p>Свидетельство о праве на наследство на транспортное средство ещё не получено.</p><h3>⚖️ Возможны два маршрута</h3><p><b>1. Не ждать окончания оформления наследства.</b> Обратиться за регистрацией транспортного средства на российский учёт на ограниченный срок 5 лет. При успешной регистрации выдаётся <b>СТС РФ на ограниченный срок 5 лет без права продажи и с запретом на внесение изменений в регистрационные данные, а также государственные регистрационные номерные знаки РФ</b>. После получения свидетельства о праве на наследство можно обратиться в МРЭО для снятия ограничения и регистрации транспортного средства на постоянный российский учёт.</p><p><b>2. Дождаться свидетельства о праве на наследство.</b> После его получения обратиться непосредственно за постоянной регистрацией транспортного средства на российский учёт на основании наследства, без промежуточной регистрации на 5 лет.</p><h3>📋 Что выбрать</h3><p>Если транспортным средством необходимо пользоваться до завершения наследственного оформления, можно использовать первый маршрут. Если временная регистрация не требуется, можно дождаться свидетельства о праве на наследство и сразу перейти к постоянной регистрации.</p><h3>🛑 Если отказали</h3><p>Не ограничивайтесь устным отказом. Подайте документы официально и получите письменное решение МРЭО с конкретным правовым основанием.</p>')}
function lnrP_inheritanceStatus(){q('Оформлено ли наследство на транспортное средство?',[['Да, имеется свидетельство о праве на наследство',lnrP_heirDisposition],['Нет, наследство ещё не оформлено',lnrP_inheritancePending]])}
function lnrP_heirs(){q('Известны ли вам наследники умершего собственника и готовы ли они участвовать в оформлении транспортного средства?',[['Да, наследники известны и готовы участвовать',lnrP_inheritanceStatus],['Наследники известны, но не хотят участвовать',()=>lnrP_five('Наличие наследников и их нежелание участвовать не создаёт у фактического владельца право собственности. Основание 5-летней регистрации — объяснение о реальных обстоятельствах владения.')],['Наследники неизвестны / связи с ними нет',()=>lnrP_five('Разыскивать наследников как предварительное условие этого маршрута Навигатор не требует. Пятилетняя регистрация не создаёт право собственности.')],['Наследников нет',()=>lnrP_five('Отсутствие наследников само по себе не делает фактического владельца собственником. Вопрос приобретения права собственности решается отдельно.')]])}
function lnrP_deceased(){q('Имеется ли у вас документ, подтверждающий ваше право собственности на транспортное средство?',[['Свидетельство о праве на наследство, выданное на моё имя',lnrP_inheritanceOwner],['Вступившее в законную силу решение суда РФ о признании за мной права собственности',lnrP_court],['Нет, такого документа у меня нет',lnrP_heirs],['Другой документ / другая ситуация',()=>other('Л-2В.1')]])}
function lnrP_five(reason){result('yellow','🟡 Регистрация на 5 лет','<p><b>Статус:</b> владение транспортным средством (не являюсь собственником по свидетельству о регистрации транспортного средства ЛНР).</p><p><b>Основание регистрации при отсутствии иного документа:</b> объяснение владельца об обстоятельствах владения транспортным средством. Указывать необходимо реальные обстоятельства получения и пользования транспортным средством.</p><p>'+reason+'</p><p><b>Практика:</b> если МРЭО становится известно о смерти собственника по свидетельству о регистрации транспортного средства ЛНР, возможен фактический отказ. В таком случае следует получить письменное решение с конкретным правовым основанием.</p><p class="warn"><b>⚠️ Нельзя оформлять ДКП задним числом от имени умершего, подделывать его подпись или использовать заведомо подложные документы.</b> Это может повлечь спор с наследниками, отказ в регистрации, а в зависимости от обстоятельств — уголовную ответственность.</p><p>Если наследники найдутся и готовы участвовать, возможен законный маршрут: оформление наследства → новая сделка с наследником → регистрация приобретателя при соблюдении условий специального порядка.</p>')}
function lnrOwnerFinal(){result('green','🟢 ПОСТОЯННАЯ РЕГИСТРАЦИЯ РФ','<p><b>⚖️ Что предусматривает закон</b></p><p>При выполнении условий этой ветки транспортное средство подпадает под специальный порядок перерегистрации на российский государственный учёт. Регистрация производится постоянно, а не на 5 лет.</p><p><b>🚘 Что получает владелец</b></p><p><b>СТС РФ, ПТС на бумажном носителе и государственные регистрационные номерные знаки РФ.</b></p><p><b>📋 Что делать</b></p><p>Обратиться в МРЭО с транспортным средством и документами: паспортом РФ, свидетельством о регистрации транспортного средства ЛНР, имеющимися документами на транспортное средство, регистрационными знаками ЛНР и документами, подтверждающими проживание на территории ЛНР до вступления ЛНР в состав Российской Федерации.</p><p><b>🛑 Если МРЭО отказывает</b></p><p>Не ограничивайтесь устным отказом. Представьте документы официально и получите письменное решение с указанием конкретного правового основания отказа. После этого можно определить дальнейший способ защиты.</p><p><b>📚 Нормативные основания</b></p><p>Точные реквизиты и пункты будут внесены после проверки окончательной редакции нового постановления Правительства РФ.</p>')}
function lnrProof(){q('Имеются ли у вас документы, подтверждающие проживание или регистрацию по месту жительства на территории ЛНР?',[['Да',lnrOwnerFinal],['Нет',()=>pending('Необходимо дополнительно подтвердить проживание или регистрацию по месту жительства на территории ЛНР')]])}
function lnrResidence(){q('Вы проживали или были зарегистрированы по месту жительства на территории ЛНР на момент принятия ЛНР в состав Российской Федерации?',[['Да, проживал в ЛНР',lnrProof],['Да, был зарегистрирован по месту жительства в ЛНР',lnrProof],['Да, проживал в ЛНР и был зарегистрирован по месту жительства',lnrProof],['Нет, не проживал и не был зарегистрирован по месту жительства в ЛНР',()=>result('red','🔴 СПЕЦИАЛЬНЫЙ ПОРЯДОК НЕ ПРИМЕНЯЕТСЯ','<p>По выбранным ответам территориальное условие для этого маршрута не выполнено.</p><h3>🛑 Если считаете вывод неверным</h3><p>Проверьте документы и измените ответы. При фактическом отказе МРЭО получите письменное решение с указанием правового основания.</p>')]],'<p>ℹ️ ЛНР принята в состав Российской Федерации <b>30 сентября 2022 года</b>.</p>')}
function lnrOwner(){q('На кого оформлено свидетельство о регистрации транспортного средства ЛНР?',[['На меня',lnrP_citizen],['На другого человека',lnrP_ownerBasis],['На умершего собственника',lnrP_deceased],['Другая ситуация / нет подходящего варианта',()=>other('Л-2')]])}

