function ukrDeceasedOwnHeirProofType(){q('Каким документом подтверждается проживание заявителя на территории нового региона на 30 сентября 2022 года?',[['Пропиской (регистрацией по месту жительства) в паспорте Украины или РФ',ukrDeceasedOwnHeirFinal],['Есть вступившее в законную силу решение суда об установлении факта проживания на необходимую дату',ukrDeceasedOwnHeirFinal],['Только другими доказательствами фактического проживания',ukrResidenceCourtResult],['Нет подтверждающих документов',ukrResidenceCourtResult],['Другая ситуация / нет подходящего варианта',()=>other('У-3.Н.3')]],'<p>ℹ️ По сообщённой практике МРЭО для этого заявителя учитывается прописка в паспорте Украины или РФ. Адрес в украинском свидетельстве о регистрации умершего собственника не подтверждает проживание наследника или приобретателя. Иные доказательства проживания рассматриваются в судебном порядке.</p>')}
function ukrDeceasedOwnHeirProof(){q('Имеются ли у вас документы, подтверждающие, что на 30 сентября 2022 года вы проживали или были зарегистрированы по месту жительства на территории нового региона?',[['Да, имеются',ukrDeceasedOwnHeirProofType],['Нет',ukrResidenceCourtResult]],'<p>ℹ️ Отсутствие подтверждающего документа на этом этапе не означает автоматический отказ. При отсутствии прописки в паспорте иные доказательства фактического проживания по сообщённой практике МРЭО рассматриваются через судебное установление юридического факта.</p>')}
function ukrDeceasedOwnHeirTerritory(){q('На 30 сентября 2022 года вы проживали или были зарегистрированы по месту жительства на территории одного из новых регионов?',[['Да — проживал на территории нового региона',ukrDeceasedOwnHeirProof],['Да — был зарегистрирован по месту жительства на территории нового региона',ukrDeceasedOwnHeirProof],['Да — проживал и был зарегистрирован по месту жительства',ukrDeceasedOwnHeirProof],['Нет — не проживал и не был зарегистрирован по месту жительства',()=>result('red','🔴 СПЕЦИАЛЬНЫЙ ПОРЯДОК ДЛЯ НАСЛЕДНИКА НЕ ПРИМЕНЯЕТСЯ','<p>Свидетельство о праве на наследство подтверждает право наследника на транспортное средство, однако для регистрации транспортного средства с украинского учёта по рассматриваемому специальному порядку требуется также территориальная связь наследника с новым регионом.</p><p>По выбранным ответам на 30 сентября 2022 года наследник не проживал и не был зарегистрирован по месту жительства на территории нового региона. Поэтому регистрация этого транспортного средства на наследника по рассматриваемому специальному порядку не предусмотрена.</p><h3>🛑 Если возник спор в МРЭО</h3><p>Не ограничивайтесь устным отказом. Подайте документы официально и получите письменное решение с конкретным правовым основанием.</p>')]],'<p>ℹ️ В украинской ветке наличие свидетельства о праве на наследство само по себе не отменяет территориальное условие специального порядка.</p>')}
function ukrDeceasedInheritance(){q('Оформлено ли наследство на транспортное средство?',[['Да — свидетельство о праве на наследство выдано мне',ukrDeceasedOwnHeirTerritory],['Да — есть вступившее в законную силу решение суда о признании моего права собственности в порядке наследования',ukrDeceasedOwnHeirTerritory],['Да — наследство оформлено на другого наследника (свидетельство или вступившее в силу решение суда)',ukrDeceasedHeirPresence],['Нет — наследство ещё не оформлено',ukrDeceasedPossessionBasis],['Другая ситуация / нет подходящего варианта',()=>other('У-3.1')]])}
function ukrDeceasedDeathDoc(){ukrDeceasedInheritance()}

function ukrOtherOwnerBasis(){q('Есть ли у вас документы, подтверждающие передачу автомобиля?',[['Да, есть доверенность',ukrOtherOwnerStatement],['Да, есть договор или другой документ',ukrOtherOwnerStatement],['Нет, документов о передаче нет',ukrOtherOwnerStatement],['Другая ситуация / нет подходящего варианта',()=>other('У-ДР-ВЛ-1')]],'<p>ℹ️ Наличие доверенности, договора или другого документа может облегчить подтверждение обстоятельств владения, но само по себе не предоставляет дополнительных прав на автомобиль и не заменяет участие собственника в МРЭО. Если собственник не участвует в оформлении, фактический владелец при соблюдении условий специального порядка может обратиться за регистрацией на ограниченный срок 5 лет. Такая регистрация не подтверждает право собственности. Если документов о передаче нет, обстоятельства приобретения и владения нужно описать в заявлении в МРЭО.</p>')}
function ukrOtherOwnerIntro(){hist.push(ukrOtherOwnerIntro);app.innerHTML='<section class="q"><div class="step-marker">УКР-ВЛАДЕЛЕЦ</div><h2>Транспортное средство зарегистрировано на другого человека</h2><p>Далее уточним, сохранились ли документы о передаче автомобиля. Их наличие само по себе не даёт дополнительных прав при регистрации на 5 лет.</p><div class="opts"><button id="ukr-other-go">Продолжить →</button></div><button class="back" id="back">← Назад</button></section>';document.getElementById('ukr-other-go').onclick=ukrOtherOwnerBasis;document.getElementById('back').onclick=()=>{hist.pop();let f=hist.pop();f&&f()}}
function ukrOwner(){q('Транспортное средство находится на украинском регистрационном учёте. На кого он зарегистрирован?',[['На меня',ukrOwnDate],['На другого человека',ukrOtherOwnerIntro],['На умершего собственника',ukrDeceasedDeathDoc],['Другая ситуация / нет подходящего варианта',()=>other('У-1')]],'<p>ℹ️ В этой ветке рассматриваются транспортные средства, находящиеся на регистрационном учёте Украины и имеющие украинские регистрационные документы.</p>')}
function currentResidence(){q('Где вы проживаете сейчас?',[['На территории одного из новых регионов, подконтрольной РФ',registrationStart],['В другом регионе Российской Федерации',registrationStart]],'<p>ℹ️ <b>Ваше нынешнее место проживания само по себе не определяет и не отменяет возможность регистрации транспортного средства.</b> Навигатор предназначен в том числе для граждан, которые ранее проживали или были зарегистрированы по месту жительства в новых регионах, но сейчас проживают в других регионах Российской Федерации.</p><p>В следующих шагах Навигатор отдельно проверит обстоятельства, которые имеют юридическое значение: где вы проживали или были зарегистрированы по месту жительства на соответствующую дату, на каком учёте находится транспортное средство, на кого оно зарегистрировано и какие документы сохранились.</p>')}
function ukrTransitRegisteredIntro(){hist.push(ukrTransitRegisteredIntro);app.innerHTML='<section class="q">'+badge('У-ТР-2')+'<h2>🇺🇦 Транспортное средство ранее было зарегистрировано на Украине</h2><p>Наличие украинских транзитных номерных знаков само по себе пока не рассматриваем как основание для прекращения проверки.</p><p>Сначала Навигатор проверит основные условия специального порядка: <b>было ли транспортное средство зарегистрировано на Украине не позднее 31 декабря 2025 года, проживание либо регистрацию по месту жительства в новом регионе и гражданство Российской Федерации</b>, а затем обстоятельства конкретной ситуации.</p><p>После прохождения этих условий Навигатор отдельно предупредит об отсутствии на момент его разработки сложившейся практики МРЭО по транспортным средствам с транзитными номерами и укажет порядок действий при отказе.</p><button class="primary" onclick="ukrTransitRegistrationDate()">Продолжить →</button></section>'}
function ukrTransitRegistrationDate(){q('Было ли транспортное средство зарегистрировано на Украине не позднее 31 декабря 2025 года?',[['Да — транспортное средство было зарегистрировано на Украине не позднее 31 декабря 2025 года',ukrTransitRegion],['Нет — транспортное средство впервые зарегистрировано на Украине после 31 декабря 2025 года',()=>result('red','🔴 СПЕЦИАЛЬНЫЙ ПОРЯДОК РЕГИСТРАЦИИ НЕ ПРИМЕНЯЕТСЯ','<p>По выбранным ответам транспортное средство не было зарегистрировано на Украине до установленной предельной даты.</p><h3>⚖️ Что предусматривает специальный порядок</h3><p>Рассматриваемый специальный порядок связывает возможность регистрации с регистрацией транспортного средства на территории Украины <b>не позднее 31 декабря 2025 года</b>.</p><h3>📋 Что делать</h3><p>Необходимо отдельно определять иной законный порядок оформления транспортного средства. Наличие транзитных номерных знаков само по себе не заменяет требование о регистрации транспортного средства на Украине до установленной даты.</p><h3>📚 Нормативное основание</h3><p>После опубликования окончательной редакции постановления здесь будет указан конкретный пункт или подпункт.</p>')]],'<p>ℹ️ Учитывается факт прежней регистрации транспортного средства на Украине, а не дата выдачи транзитных номерных знаков.</p>')}
function ukrTransitCitizen(){q('Являетесь ли вы гражданином Российской Федерации?',[['Да',ukrTransitPracticeResult],['Нет',()=>result('red','🔴 СНАЧАЛА НЕОБХОДИМО ПОЛУЧИТЬ ПАСПОРТ ГРАЖДАНИНА РФ','<p>Для применения рассматриваемого специального порядка необходимо соответствовать установленной постановлением категории граждан.</p><h3>📋 Что необходимо сделать</h3><ol><li><b>Получить паспорт гражданина Российской Федерации.</b></li><li>Подтвердить, что на момент принятия соответствующего нового региона в состав Российской Федерации вы <b>проживали либо были зарегистрированы по месту жительства</b> на территории этого региона.</li><li>После этого повторно пройти эту ветку Навигатора.</li></ol>')]])}
function ukrTransitRegion(){q('На момент принятия нового региона в состав Российской Федерации вы проживали или были зарегистрированы по месту жительства на территории одного из новых регионов?',[['Да — был зарегистрирован по месту жительства («прописка»)',ukrTransitCitizen],['Да — проживал, но регистрации по месту жительства («прописки») в паспорте не было',()=>result('yellow','🟡 НЕОБХОДИМО УСТАНОВИТЬ ФАКТ ПРОЖИВАНИЯ ЧЕРЕЗ СУД','<p>По сложившейся практике МРЭО для подтверждения проживания принимает регистрацию по месту жительства («прописку») в паспорте. Иные документы сами по себе не заменяют её в административной процедуре.</p><h3>📋 Что делать</h3><p>Необходимо обратиться в суд с заявлением об установлении юридического факта проживания на территории соответствующего нового региона. Имеющиеся документы и сведения, в том числе данные государственных органов, могут использоваться как доказательства в суде.</p><p>После вступления решения суда в законную силу вернитесь к вопросу регистрации транспортного средства в МРЭО.</p>')],['Нет — не проживал и не был зарегистрирован по месту жительства',()=>result('red','🔴 СПЕЦИАЛЬНЫЙ ПОРЯДОК РЕГИСТРАЦИИ НЕ ПРИМЕНЯЕТСЯ','<p>По выбранным ответам отсутствует требуемая территориальная связь с новым регионом.</p><p>Наличие украинских транзитных номерных знаков не создаёт самостоятельного права на регистрацию по специальному порядку.</p><h3>📚 Нормативное основание</h3><p>После опубликования окончательной редакции постановления здесь будет указан конкретный пункт или подпункт.</p>')]],'<p>ℹ️ Если прописки в паспорте не было, но вы фактически проживали в новом регионе, Навигатор направит по судебному маршруту установления факта проживания.</p>')}
function ukrTransitPracticeResult(){result('yellow','🟡 ВОЗМОЖНОСТЬ РЕГИСТРАЦИИ ТРЕБУЕТ ПРОВЕРКИ В МРЭО','<p>По выбранным ответам транспортное средство <b>было зарегистрировано на Украине не позднее 31 декабря 2025 года</b>, а основные условия специального порядка со стороны заявителя выполняются.</p><h3>⚠️ Транспортное средство на украинских транзитных номерах</h3><p>На момент разработки Навигатора сложившаяся практика МРЭО по регистрации таких транспортных средств в рамках нового специального порядка отсутствует.</p><p>Если транспортное средство было зарегистрировано на Украине не позднее 31 декабря 2025 года, наличие транзитных номерных знаков и временных регистрационных документов само по себе не означает, что транспортное средство исключён из специального порядка. Рассматриваемое постановление отдельно не исключает перерегистрацию только по причине наличия транзитных номерных знаков или временных документов.</p><h3>📋 Что делать</h3><ol><li>Обратитесь в МРЭО с транспортным средством и всеми сохранившимися украинскими регистрационными и транзитными документами.</li><li>Подайте заявление на регистрацию по специальному порядку.</li><li>Если откажут именно из-за транзитных номерных знаков или временного документа, потребуйте <b>письменное решение об отказе</b> с указанием конкретного нормативного основания.</li></ol><h3>🛑 Если МРЭО отказало</h3><p>Письменный отказ можно обжаловать <b>руководителю соответствующего подразделения Госавтоинспекции либо в суде</b>. В жалобе следует указывать, что транспортное средство было зарегистрировано на Украине до установленной даты, а специальный порядок прямо не исключает его только по причине последующей выдачи транзитных номерных знаков или временных документов.</p><p><b>Важно:</b> до появления устойчивой административной или судебной практики Навигатор не утверждает, что МРЭО обязано зарегистрировать любой транспортное средство с транзитными номерами. Конкретное решение зависит от документов и обстоятельств транспортного средства.</p><h3>📚 Нормативное основание</h3><p>После официального опубликования окончательной редакции постановления здесь будет указан конкретный пункт или подпункт, регулирующий эту ситуацию.</p>')}
function ukrTransitReason(){q('Почему на транспортном средстве установлены украинские транзитные номерные знаки?',[['Транспортное средство ранее было зарегистрировано на Украине, затем его сняли с регистрационного учёта',ukrRemovedStart],['Транспортное средство было приобретено на Украине и получило транзитные номера для дальнейшей регистрации',ukrTransitRegisteredIntro],['Транспортное средство ввезено и растаможено на Украине, получило транзитные номера, но на постоянный регистрационный учёт Украины не ставился',ukrImportDate],['Другая ситуация / нет подходящего варианта',()=>other('У-ТР-1')]],'<p>ℹ️ Для Навигатора важно установить происхождение транзитных номеров: транспортное средство могло ранее находиться на украинском регистрационном учёте либо получить транзитные номера без постановки на постоянный регистрационный учёт Украины.</p>')}
function registrationStart(){q('На каком учёте находится транспортное средство?',[['ДНР',d1],['ЛНР',lnrD1],['Украина',ukrIntro],['Другая ситуация (например: транспортное средство растаможено на Украине, но не зарегистрировано; транзитные номера; снят с регистрационного учёта; документы утрачены и т. д.)',()=>q('Какая именно ситуация?',[['Транспортное средство ввезено из-за рубежа, растаможено на Украине, но не зарегистрирован на Украине',ukrImportDate],['Транзитные номера Украины',ukrTransitReason],['Снято с украинского регистрационного учёта',ukrRemovedStart],['Регистрационные документы утрачены',()=>pending('Документы утрачены')],['Транспортное средство никогда не было зарегистрировано',()=>pending('Никогда не было зарегистрирован')],['Иностранный учёт другого государства',()=>pending('Иностранный учёт')],['Другая ситуация',()=>other('ДР-1.7')]])]],'Выберите не регион, где транспортное средство находится сейчас, а регистрационный учёт по имеющимся документам и государственным номерам.')}

function ukrRegistrationEligibility(next,applicant='self'){q('Было ли транспортное средство зарегистрировано на Украине не позднее 31 декабря 2025 года?',[
 ['Да — транспортное средство было зарегистрировано на Украине не позднее 31 декабря 2025 года',()=>ukrApplicantCitizen(next,applicant)],
 ['Нет — транспортное средство впервые зарегистрировано на Украине после 31 декабря 2025 года',()=>result('red','🔴 СПЕЦИАЛЬНЫЙ ПОРЯДОК ПО ЭТОЙ ВЕТКЕ НЕ ПРИМЕНЯЕТСЯ','<p>Условие о регистрации транспортного средства на Украине не позднее 31 декабря 2025 года не выполнено. Необходимо отдельно определить иной законный маршрут оформления.</p>')]
 ],'<p>ℹ️ Проверяется дата регистрации транспортного средства на Украине, а не дата оформления наследства или передачи транспортного средства заявителю.</p>')}
function ukrApplicantCitizen(next,applicant='self'){q(applicant==='heir'?'Является ли наследник, на которого планируется регистрация автомобиля, гражданином Российской Федерации?':'Являетесь ли вы гражданином Российской Федерации?',[
 ['Да',next],
 ['Нет',()=>result('yellow','🟡 ГРАЖДАНСТВО РФ ЗАЯВИТЕЛЯ НЕ ПОДТВЕРЖДЕНО',applicant==='heir'?'<p>Для регистрации непосредственно на наследника необходимо проверить выполнение условия о гражданстве РФ именно наследником. По выбранному ответу оно не выполняется. Получение гражданства пользователем Навигатора вместо наследника этого условия не заменяет.</p>':'<p>Для выбранного маршрута необходимо подтвердить гражданство РФ заявителя. По вашему ответу это условие не выполняется. После получения гражданства и паспорта РФ можно повторно проверить условия регистрации.</p>')]
 ])}
function ukrFiveYearResidenceProof(){q('Чем подтверждается ваше постоянное проживание в новом регионе на юридически значимую дату либо ранее, если вы затем выехали в другой субъект РФ?',[['Пропиской (регистрацией по месту жительства) в паспорте Украины или РФ',ukrOtherOwnerFiveResult],['Есть вступившее в законную силу решение суда об установлении факта проживания на необходимую дату',ukrOtherOwnerFiveResult],['Только иными документами или свидетельствами о фактическом проживании',ukrResidenceCourtResult],['Документов нет',ukrResidenceCourtResult],['Другая ситуация / требуется уточнение',()=>other('У-5.ПР')]],'<p>ℹ️ Адрес в украинском свидетельстве о регистрации автомобиля, оформленном на другого человека, не подтверждает ваше проживание. По сообщённой практике МРЭО иные доказательства фактического проживания требуют судебного установления юридического факта.</p>')}
function ukrOtherOwnerFiveResult(){ukrRegistrationEligibility(ukrOtherOwnerFiveResultRender)}
