function ukrImportDate(){q('Когда транспортное средство было ввезено и растаможено на Украине?',[
['Не позднее 31 декабря 2025 года',ukrImportDocuments],
['После 31 декабря 2025 года',ukrImportDocuments]
],'<p>ℹ️ Эта ветка предназначена для транспортного средства, ввезённого из-за рубежа и растаможенного на Украине, но не поставленного на украинский регистрационный учёт. Дата растаможки имеет значение для оценки обстоятельств судом; оба ответа ведут к единому судебному маршруту.</p>','Q-УКР-ИМП-1')}
function ukrImportDocuments(){q('Сохранились ли документы, подтверждающие ввоз транспортного средства и его таможенное оформление на Украине?',[
['Да',ukrImportResidence],['Нет',ukrImportRestore]
],'','Q-УКР-ИМП-2')}
function ukrImportRestore(){q('🟡 Необходимо восстановить документы или собрать доказательства таможенного оформления',[
['Продолжить',ukrImportResidence]
],'<p>Отсутствие документов на руках не означает, что транспортное средство не проходил таможенное оформление на Украине. Однако для дальнейшего судебного разбирательства потребуется подтвердить этот факт.</p><p>Попробуйте получить копии документов или сведения об оформлении у таможенного органа, таможенного представителя либо лица, занимавшегося ввозом транспортного средства. Сохраните имеющиеся копии, фотографии документов, переписку и ответы на запросы.</p><p>Если восстановить документы невозможно, необходимо объяснить причины их отсутствия и представить имеющиеся доказательства. Их достаточность оценит суд.</p>','INFO-УКР-ИМП-ДОК')}
function ukrImportResidence(){q('Проживали ли вы или были зарегистрированы по месту жительства на территории одного из новых регионов на момент принятия этого региона в состав Российской Федерации?',[
['Да — был зарегистрирован по месту жительства («прописка»)',ukrImportCitizen],
['Да — проживал, но регистрации по месту жительства («прописки») не было',ukrImportResidenceCourt],
['Нет — не проживал и не был зарегистрирован по месту жительства',()=>result('red','🔴 СПЕЦИАЛЬНЫЙ ПОРЯДОК НЕ ПРИМЕНЯЕТСЯ','<p>Территориальное условие рассматриваемого специального порядка не выполнено. Это не означает запрета регистрации по другим законным основаниям.</p>','R-УКР-ИМП-ТЕР')]
],'<p>ℹ️ ДНР, ЛНР, Запорожская и Херсонская области приняты в состав Российской Федерации 30 сентября 2022 года.</p>','Q-УКР-ИМП-3')}
function ukrImportResidenceCourt(){q('🟡 Необходимо установить факт проживания через суд',[
['Продолжить проверку остальных условий',ukrImportCitizen]
],'<p>Для этой ветки предусмотрено установление юридического факта проживания на территории соответствующего нового региона на 30 сентября 2022 года через суд. Подготовьте имеющиеся доказательства проживания. Продолжение проверки не означает, что факт проживания уже установлен.</p>','INFO-УКР-ИМП-ПРОЖ')}
function ukrImportCitizen(){q('Являетесь ли вы гражданином Российской Федерации?',[
['Да',ukrImportCourt],
['Нет',()=>result('yellow','🟡 СНАЧАЛА НЕОБХОДИМО ПОЛУЧИТЬ ГРАЖДАНСТВО И ПАСПОРТ РФ','<p>После получения гражданства и паспорта РФ вернитесь в эту ветку Навигатора. Для обращения в МРЭО потребуется паспорт гражданина РФ.</p>','R-УКР-ИМП-ПАСП')]
],'<p>ℹ️ Для дальнейшего обращения потребуется паспорт гражданина РФ.</p>','Q-УКР-ИМП-4')}
function ukrImportCourt(){result('yellow','🟡 ТРАНСПОРТНОЕ СРЕДСТВО РАСТАМОЖЕНО НА УКРАИНЕ, НО НЕ ЗАРЕГИСТРИРОВАНО — СУДЕБНЫЙ МАРШРУТ',
'<p>В рассматриваемой ветке не выполнено условие о регистрации транспортного средства на Украине. Документы о таможенном оформлении подтверждают растаможку, но не заменяют регистрационные документы.</p><p>Для этой категории Навигатор предусматривает единый судебный маршрут независимо от даты растаможки. Если факт проживания ещё не установлен или документы о растаможке не восстановлены, необходимо отдельно подготовить соответствующие доказательства.</p><h3>📋 Порядок действий</h3><ol><li>Подать в МРЭО заявление о регистрации с имеющимися подтверждающими документами.</li><li>Получить письменное решение с конкретными основаниями отказа.</li><li>При отказе обратиться в суд, определив требования с учётом содержания решения и документов на транспортное средство.</li></ol><h3>⚖️ Позиция для суда</h3><p>Если транспортное средство не было зарегистрировано на Украине из-за боевых действий и обстоятельств, не зависящих от владельца, изложите эти обстоятельства и представьте подтверждения. Имеют значение даты приобретения, ввоза и растаможки, место нахождения транспортного средства и владельца, прекращение работы регистрационных органов, боевые действия, эвакуация, обращения и ответы органов. Указывайте только реальные обстоятельства.</p><p>Оспаривание отказа МРЭО и признание права собственности — разные требования. Если спор касается отказа государственного органа, рассматривается административное оспаривание. Если необходимо разрешить вопрос о принадлежности транспортного средства, отдельно оценивается необходимость гражданского иска.</p><h3>Будьте готовы к нескольким судебным инстанциям</h3><p>Суд первой инстанции может отказать в удовлетворении требований. Поэтому необходимо быть готовым к обжалованию решения в апелляционном и кассационном порядке, а при сохранении оснований для дальнейшего обжалования — к обращению в Верховный Суд Российской Федерации.</p><p>Судебный процесс может потребовать значительного времени. Обращение в Верховный Суд не гарантирует передачи жалобы на рассмотрение или положительного решения, но даёт дополнительную возможность добиться решения в вашу пользу.</p><p>Обстоятельства боевых действий подлежат оценке судом и не гарантируют положительного решения.</p>','R-УКР-ИМП-СУД')}

function start(){hist=[];currentResidence()}start();
function dnrMovedResidence(ordinary,moved){q('Вы проживали или были зарегистрированы по месту жительства на территории ДНР на момент принятия ДНР в состав Российской Федерации?',[
['Да, проживал в ДНР',ordinary],
['Да, был зарегистрирован по месту жительства в ДНР',ordinary],
['Да, проживал в ДНР и был зарегистрирован по месту жительства',ordinary],
["До 2022 года жил на ныне освобождённой территории ДНР, но выехал на территорию ДНР под контролем властей Украины",()=>dnrMovedCustoms(()=>dnrMovedCitizen(moved))],
['Нет, не проживал и не был зарегистрирован по месту жительства в ДНР',()=>result('red','🔴 ТРЕБУЕТСЯ ИНОЙ МАРШРУТ','<p>По выбранному ответу территориальное условие этой ветки не подтверждено.</p>')]
],accession,'Q-ДНР-ПРОЖИВАНИЕ')}
function dnrMovedCitizen(next){q('Являетесь ли вы гражданином Российской Федерации?',[
['Да',next],['Нет',()=>result('yellow','🟡 НЕОБХОДИМО ПОЛУЧИТЬ ГРАЖДАНСТВО И ПАСПОРТ РФ','<p>После получения гражданства и паспорта РФ вернитесь к проверке условий перерегистрации на российский учёт.</p>')]
],'','Q-ДНР-ПЕРЕЕЗД-ПАСПОРТ')}
function dnrMovedCustoms(next){q('Находится ли транспортное средство под таможенным контролем?',[
['Нет',next],
['Да',()=>dnrMovedCourt(next)]
],'<p>Ориентируйтесь на таможенные документы и официальные сведения таможенного органа. Само отсутствие документов на руках не подтверждает отсутствие таможенного контроля.</p>','Q-ДНР-ПЕРЕЕЗД-ТАМОЖНЯ')}
function dnrMovedCourt(next){q('🟡 Подтверждение проживания и разрешение вопроса о таможенном контроле через суд',[
['Таможенный контроль прекращён — продолжить проверку условий регистрации',next]
],'<p>Подготовьте доказательства постоянного проживания на территории ДНР, находившейся под контролем Украины, и обстоятельств переезда. Если необходимо судебное подтверждение, определите юридически значимый период проживания и требования с учётом документов и позиции таможенного органа.</p><p>Вступившее в законную силу решение суда представьте в таможенный орган с заявлением о прекращении таможенного контроля. При отказе получите письменное решение и рассмотрите его обжалование.</p><p><b>Решение только об установлении факта проживания не прекращает таможенный контроль автоматически.</b> При споре с таможней может потребоваться оспаривание её решения. Продолжайте регистрацию после официального подтверждения прекращения контроля и выполнения остальных условий соответствующей ветки.</p>','INFO-ДНР-ПЕРЕЕЗД-СУД')}


// Согласованная ветка: ТС снято с украинского учёта.
// Ответы передаются копиями: возврат назад не сохраняет ответы из отменённых шагов.
function urQuestion(n,title,options,state){q(title,options.map(([label,patch,next])=>[label,()=>next({...state,...patch})]),'', 'Q-УКР-СНЯТ-'+n)}
function urStop(key,title,text){result('yellow',title,'<p>'+text+'</p>','R-УКР-СНЯТ-'+key)}
function ukrRemovedStart(){urDocuments({})}
function urDocuments(state){
 const labels=[['registration','Украинское свидетельство о регистрации (техпаспорт)'],['card','Регистрационная / учётная карточка'],['extract','Выписка или справка о прежней украинской регистрации'],['purchase','Договор купли-продажи, справка-счёт или другой документ о приобретении'],['gift','Договор дарения'],['poa','Доверенность'],['lease','Договор лизинга'],['holding','Другой документ о праве владения'],['removal','Отдельный документ о снятии с украинского учёта']];
 hist.push(()=>urDocuments(state));
 app.innerHTML='<section class="q">'+badge('Q-УКР-СНЯТ-1')+'<h2>Какие документы сохранились после снятия транспортного средства с украинского учёта?</h2><p>Выберите все имеющиеся документы. Если документов нет, оставьте пункты пустыми.</p><div class="opts">'+labels.map(([key,label])=>'<label><input type="checkbox" data-doc="'+key+'" '+(state.docs?.includes(key)?'checked':'')+'> '+label+'</label>').join('')+'</div><button id="ur-next" class="primary">Продолжить →</button><button id="back" class="back">← Назад</button></section>';
 document.getElementById('back').onclick=()=>{hist.pop();const f=hist.pop();if(f)f()};
 document.getElementById('ur-next').onclick=()=>{const docs=[...app.querySelectorAll('[data-doc]:checked')].map(e=>e.dataset.doc);const t={...state,docs};if(!docs.some(x=>['registration','card','extract'].includes(x)))return urStop('ДОК','Необходимо получить подтверждение прежней украинской регистрации','Среди имеющихся документов нет свидетельства о регистрации, регистрационной / учётной карточки или другого документа, подтверждающего прежнюю регистрацию транспортного средства на Украине. Документ о приобретении сам по себе не заменяет подтверждение прежней регистрации. После получения подтверждающего документа вернитесь к проверке.');if(docs.includes('registration')||docs.includes('card'))urMark(t);else urRemoval(t)};
}
function urMark(s){urQuestion(2,'Есть ли в свидетельстве о регистрации (техпаспорте) или регистрационной / учётной карточке отметка о снятии транспортного средства с регистрационного учёта на Украине?', [['Да',{mark:true},urDate],['Нет',{mark:false},urRemoval]],s)}
function urRemoval(s){if(s.docs.includes('removal'))return urRemovalType(s);urQuestion(22,'Имеется ли отдельный документ, подтверждающий снятие транспортного средства с украинского регистрационного учёта?', [['Да',{},urRemovalType],['Нет',{},urNotRemoved]],s)}
function urNotRemoved(){q('Снятие с украинского учёта не подтверждено имеющимися документами.',[['Перейти к ветке «Транспортное средство на украинском учёте»',ukrIntro]],'<p>В регистрационных документах нет отметки о снятии с учёта, отдельного подтверждающего документа также нет.</p>','R-УКР-СНЯТ-СНЯТИЕ')}
function urRemovalType(s){urQuestion(23,'Какой отдельный документ подтверждает снятие транспортного средства с украинского регистрационного учёта?', [['Выписка или справка украинского регистрационного органа',{removalType:'Выписка или справка украинского регистрационного органа'},urDate],['Другой документ, выданный украинским регистрационным органом и подтверждающий снятие с учёта',{removalType:'Документ украинского регистрационного органа о снятии с учёта'},urDate]],s)}
function urDate(s){urQuestion(3,'Было ли транспортное средство зарегистрировано на Украине не позднее 31 декабря 2025 года?', [['Да — было зарегистрировано не позднее 31 декабря 2025 года',{},urResidence],['Нет — впервые зарегистрировано после 31 декабря 2025 года',{},()=>urStop('ДАТА','Дата первой украинской регистрации выходит за пределы этой ветки','Вы указали, что транспортное средство впервые зарегистрировано на Украине после 31 декабря 2025 года. Этот маршрут Навигатора рассматривает транспортные средства, зарегистрированные не позднее указанной даты.')]],s)}
function urResidence(s){urQuestion(4,'Проживали ли вы или были зарегистрированы по месту жительства на территории одного из новых регионов на момент принятия этого региона в состав Российской Федерации?', [['Да — был зарегистрирован по месту жительства («прописка»)',{residence:'registered'},urPassport],['Да — проживал, но регистрации по месту жительства («прописки») не было',{residence:'lived'},urProof],['Нет — не проживал и не был зарегистрирован по месту жительства',{},()=>urStop('ТЕР','Территориальное условие этой ветки не выполнено','Вы указали, что на 30 сентября 2022 года не проживали и не были зарегистрированы по месту жительства на территории новых регионов. По этому маршруту Навигатор не переходит к дальнейшей проверке регистрации на ваше имя.')]],s)}
function urProof(s){urQuestion(24,'Имеются ли у вас документы, подтверждающие проживание на территории соответствующего нового региона на 30 сентября 2022 года?', [['Да',{},urPassport],['Нет',{},()=>urStop('ПРОЖ','Необходимо документально подтвердить проживание','Вы указали, что проживали на территории соответствующего нового региона на 30 сентября 2022 года, но подтверждающих документов сейчас нет. Следующий шаг — собрать документы, подтверждающие этот факт, затем вернуться к проверке.')]],s)}
function urPassport(s){urQuestion(5,'Имеется ли у вас паспорт гражданина Российской Федерации?', [['Да',{},urOwner],['Нет',{},()=>urStop('ПАСП','Для продолжения этого маршрута необходим паспорт гражданина Российской Федерации','После получения паспорта РФ вернитесь к проверке.')]],s)}
function urOwner(s){urQuestion(6,'На кого было зарегистрировано транспортное средство на Украине до снятия с учёта?', [['На меня',{route:'own'},urCustoms],['На другого человека',{dead:false},urAcquisition],['На умершего человека',{dead:true},urInheritance]],s)}
function urInheritance(s){urQuestion(8,'Имеется ли свидетельство о праве на наследство на это транспортное средство, выданное на Украине?', [['Да — выдано на моё имя',{route:'heir'},urCustoms],['Да — выдано на имя другого наследника',{otherHeir:true},urHeirTransfer],['Нет — такого свидетельства нет',{},urLifetime]],s)}
function urHeirTransfer(s){urQuestion(9,'Как оформлена передача транспортного средства от наследника вам?', [['По договору купли-продажи',{document:'Договор купли-продажи',route:'five'},urCustoms],['По договору дарения',{document:'Договор дарения',route:'five'},urCustoms],['Передача пока не оформлена',{},()=>urStop('НАСЛ-ПЕР','Передача транспортного средства вам пока не оформлена','Украинское свидетельство о праве на наследство выдано другому наследнику. Необходимо документально оформить передачу транспортного средства от наследника вам. После этого можно продолжить проверку условий регистрации на 5 лет без права продажи.<br><br>При покупке не производите полный расчёт до проверки возможности оформления и регистрации. При наличном расчёте оформляйте расписку, при переводе указывайте понятное назначение платежа.')]],s)}
function urLifetime(s){urQuestion(10,'Транспортное средство было передано вам при жизни человека, на которого оно было зарегистрировано на Украине?', [['Да — имеется документ о приобретении или праве владения',{},urKnownDocument],['Да — транспортное средство и документы переданы без оформления сделки',{document:null,route:'five'},urCustoms],['Нет — транспортное средство оказалось у меня после его смерти',{},()=>urStop('НАСЛ','Отсутствует документ, подтверждающий наследование транспортного средства','Для продолжения этой ветки необходимо свидетельство о праве на наследство на это транспортное средство, выданное на Украине: на ваше имя либо на имя наследника, который оформил передачу вам. Вопросы оформления или признания наследства в РФ эта ветка Навигатора не рассматривает.')]],s)}
const urDocNames={purchase:'Договор купли-продажи, справка-счёт или другой документ о приобретении',gift:'Договор дарения',poa:'Доверенность',lease:'Договор лизинга',holding:'Другой документ о праве владения'};
function urKnownDocument(s){const available=s.docs.filter(k=>urDocNames[k]);if(available.length===1)return urDocumentSelected({...s,document:urDocNames[available[0]],kind:available[0]});if(available.length>1)return urQuestion(s.dead?11:21,'Какой из имеющихся документов является основанием вашего приобретения или владения?',available.map(k=>[urDocNames[k],{document:urDocNames[k],kind:k},urDocumentSelected]),s);urQuestion(s.dead?11:21,'Какой документ подтверждает приобретение или право владения транспортным средством?',Object.entries(urDocNames).map(([kind,document])=>[document,{kind,document},urDocumentSelected]),s)}
function urAcquisition(s){if(s.docs.some(k=>urDocNames[k]))return urKnownDocument(s);urQuestion(7,'Имеется ли у вас документ, подтверждающий приобретение транспортного средства или право владения им?', [['Да — договор купли-продажи, справка-счёт или другой документ о приобретении',{kind:'purchase',document:urDocNames.purchase},urDocumentSelected],['Да — доверенность, договор лизинга или другой документ о праве владения',{},urKnownDocument],['Нет — транспортное средство и регистрационные документы переданы мне без оформления сделки',{document:null},urPresence]],s)}
function urDocumentSelected(s){if(['purchase','gift'].includes(s.kind))return urRecipient(s);if(s.dead)return urCustoms({...s,route:'five'});urPresence(s)}
function urRecipient(s){urQuestion(16,'Кто указан в документе о приобретении транспортного средства в качестве покупателя или получателя?', [['Я',{},s.dead?t=>urCustoms({...t,route:'five'}):urPresence],['Другой человек',{},urChain]],s)}
function urChain(s){urQuestion(17,'Оформлена ли передача транспортного средства от этого человека вам?', [['Да — по договору купли-продажи',{document:'Документ о приобретении промежуточным покупателем и договор купли-продажи на ваше имя'},s.dead?t=>urCustoms({...t,route:'five'}):urPresence],['Да — по договору дарения',{document:'Документ о приобретении промежуточным покупателем и договор дарения на ваше имя'},s.dead?t=>urCustoms({...t,route:'five'}):urPresence],['Нет — передача не оформлена',{},()=>urStop('ПЕР','Передача транспортного средства вам не оформлена','В имеющемся документе о приобретении указан другой человек. Для продолжения проверки необходимо уточнить документальное основание вашего владения транспортным средством. Присутствие этого человека в МРЭО само по себе не меняет маршрут регистрации на 5 лет без права продажи при отсутствии собственника по украинскому свидетельству о регистрации.')]],s)}
function urPresence(s){if(s.dead)return urCustoms({...s,route:'five'});urQuestion(18,'Будет ли присутствовать в МРЭО человек, на которого транспортное средство было зарегистрировано на Украине до снятия с учёта?', [['Да',{route:'sale'},urCustoms],['Нет',{route:'five'},urCustoms]],s)}
function urCustoms(s){urQuestion(15,'Находится ли транспортное средство под таможенным контролем?', [['Да',{},()=>urStop('ТАМ','Необходимо урегулировать таможенный статус транспортного средства','Дальнейшую проверку по этой ветке можно продолжить после прекращения таможенного контроля. После урегулирования статуса вернитесь к этому вопросу и выберите «Нет».')],['Нет',{},urFinal]],s)}
function urFinal(s){
 const docs=['Паспорт гражданина РФ заявителя.','Заявление о регистрации транспортного средства.'];
 if(s.route==='sale')docs.push('Документ, удостоверяющий личность прежнего собственника.','Документ о передаче права собственности заявителю — договор купли-продажи, дарения или иной документ о приобретении.');
 if(s.route==='heir')docs.push('Украинское свидетельство о праве на наследство на это транспортное средство, выданное на ваше имя.');
 if(s.docs.includes('registration'))docs.push('Украинское свидетельство о регистрации (техпаспорт).');
 if(s.docs.includes('card'))docs.push('Регистрационная / учётная карточка.');
 if(s.docs.includes('extract'))docs.push('Выписка или справка о прежней украинской регистрации.');
 docs.push(s.mark?'Отметка о снятии с украинского учёта в регистрационных документах.':s.removalType+'.');
 if(s.route==='five'&&s.document)docs.push(s.document+'.');
 if(s.otherHeir)docs.push('Украинское свидетельство о праве на наследство, выданное наследнику, у которого приобретено транспортное средство.');
 if(s.residence==='lived')docs.push('Документы, подтверждающие проживание на территории соответствующего нового региона на 30 сентября 2022 года.');
 let body='<h3>Документы</h3><ul>'+docs.map(d=>'<li>'+d+'</li>').join('')+'</ul><h3>Дальнейшие действия</h3><p>Подготовьте документы по сформированному перечню и предоставьте транспортное средство для осмотра в МРЭО.</p>';
 if(s.route==='sale')body+='<p>Обращайтесь в МРЭО вместе с прежним собственником. Если передача права собственности ещё не оформлена, необходимо документально оформить её.</p>';
 if(s.kind==='purchase'||s.document?.includes('купли-продажи'))body+='<h3>Безопасная передача денег</h3><p>Не производите полный расчёт до проверки возможности оформления и регистрации. Аванс фиксируйте письменно; при наличном расчёте оформляйте расписку, при переводе указывайте понятное назначение платежа.</p>';
 result(s.route==='five'?'yellow':'green',s.route==='five'?'Регистрация на 5 лет без права продажи':'Постоянная регистрация на ваше имя',body,'R-УКР-СНЯТ-'+s.route.toUpperCase());
}
